class Work(Case):
 def __init__(self,sid,title,task,name,role,history,initial):
  p,h=voice(name,role,*history);super().__init__(sid,title,task,'Current commission. Open the original contracts, named conversations and actual records through these links; the card is not a completed plan.|本次委托，原合同、各方会话和实际记录都可从链接打开，卡片不是现成方案。',p,h,120)
  self.sid=sid;service(self,'Business actions record actual submitted objects and receipts. A request or a local note does not complete an external obligation.|业务动作按实际提交对象和回执记录，请求或本地备注不等于完成外部义务。',initial)
 def evidence(self,key,title,text,**attrs):self.source(key,title,txt(key,text,**attrs))
 def person(self,key,name,text,topic='confirm',answer=None,terms=None,fields=None):
  contact(self,key,key+'-dm',name,text,topics=(topic,),schema={k:{'type':'string'} for k in (terms or {})} or None)
  if answer:self.answer(key+'-dm',topic,answer,details=terms,fields=None if fields is False else (fields or {'confirmed':True}))
 def desk(self,key,desc,receipt,updates,requires=None,params=None,**extra):
  if params:
   schema={k:({'type':'number'} if type(v) in (int,float) else {'type':'string'}) for k,v in params.items()}
   field_map={}
   for parameter,value in params.items():
    for field,current in updates.items():
     if type(value) is type(current) and value==current:field_map[parameter]=field
   extra.update(param_schema=schema,parameter_record={'resource':'state','field':key+'_submission','field_map':field_map})
   if self.sid!='t5-03' and 'param_variants' not in extra:
    extra.setdefault('param_values',deepcopy(params))
    if 'route' in params:
     extra['param_values'].pop('route');extra['param_variants']=[{'param_values':{'route':';'.join(order)}}for order in permutations(params['route'].split(';'))]
   # Public technical vocabulary lists both outcomes, without disclosing the branch.
   if 'camera_status' in schema:schema['camera_status']={'type':'string','enum':['appointment_U8','held_pending']}
   if 'method' in schema:schema['method']={'type':'string','enum':['cancel_pending','repayment']}
   if params.get('source')=='artwork30':schema['source']={'type':'string','enum':['artwork30']}
   if params.get('insert')=='returned_clean':schema['insert']={'type':'string','enum':['returned_clean','sealed_spare']}
  if params:receipt='The submitted business card was executed; its exact object, destination and amount are recorded in this receipt.|业务已按提交卡执行，本回执记录准确对象、去向和金额。'
  action=op(self,key,desc,receipt,sets={'state':updates},requires=requires,**extra)
  if params:
   next(z for z in self.find('service')['options'] if z['key']==key)['param_schema']=schema
   action['params']=deepcopy(params)
  return action
 def public(self,main,answers):
  rs=[post('main',main)]
  for i,(q,wrong) in enumerate(answers,1):rs.extend([comment('q'+str(i),q,'Reader'+str(i)),old('old'+str(i),wrong,'q'+str(i))])
  self.source('public','Current public post and original replies|当前公开帖及原答复',*rs)
 def goals(self,rows):common_goals(self,rows)
 def package(self,actions,short,near,near_goal,other,other_goal,notes):
  c=plans(self,actions,short,near,near_goal,other,other_goal)
  # Directed route-entry order is semantically immaterial for consent too.
  for answer in c['answers'].values():
   terms=answer.get('request_fields',{})
   if isinstance(terms.get('route'),str):
    for order in permutations(terms['route'].split(';')):
     variant=deepcopy({k:v for k,v in answer.items()if k!='variants'});variant['request_fields']['route']=';'.join(order);answer.setdefault('variants',[]).append(variant)
  c['review_notes']=notes
  return c

def confirmed(*people):return {'fields':{p+'-dm-answer':{'confirmed':True} for p in people}}
def obtained(*ids):return {'revealed':list(ids)}
def wait_for(*ids):return {'action':'WAIT_FOR_IDS','ids':list(ids),'until':119}
def queries(keys):return [lookup(k) for k in keys]

