def equipment(branch='A'):
 proxy=branch=='A';collector='acct-S17' if proxy else 'acct-B02'
 x=Work('t5-04','The roommate may return a case without collecting the tent|室友能还箱，不代表能拿帐篷',
 'D1 17:00. Complete our two paid equipment handovers and the existing C14 case return. Buyer B may nominate a current T82 collector in the original order; yesterday\'s stove screenshot does not cover it. The returned C14 must be actually accepted before owner Lee releases reserved case C41 for Bo\'s paid K41 kit. B has a staffed own-pickup slot this round if proxy is declined. Respect the separate return-only authority, actual scans and original deposit beneficiary. Correct our three public claims and privately report actual results to B, returner S and next borrower Bo.|D1 17:00。完成两笔已付装备交物及原C14箱归还。B可在T82原单指定本次领取人，昨天炉具截图不管这单。C14实收后Lee才放保留C41给Bo已付K41套件。若不代取，B本轮有值班自取时段。分清只还箱授权、实际扫码和原押金收款人，改三处公开说法，向B、还箱S、下位Bo私告结果。',
 'Toby','I look after the outdoor club kit desk. I keep collection messages short and explain the one condition that matters for the person in front of me.|我管户外社装备台，领取消息短，先说眼前这位要紧的那一个条件。',[
 'The tent is dry. The packing bag has apparently chosen a different career.|帐篷干了，收纳袋好像决定转行了。',
 'Can you send the order number as well as the nickname? We have two people called Sam.|昵称之外也发单号行吗？有两位都叫Sam。',
 'The case was on its way back, not checked in. I have fixed the next pickup message.|箱子只是正在还，不是签入了，下位领取消息改了。'],{'T82':'paid_unfulfilled','C14':'out','C41':'held_by_Lee','K41':'paid_unfulfilled','deposit':'held'})
 for k,title,text in [('orders','Two current paid orders|两笔本次已付单','T82 tent belongs to buyer B/acct-B02, paid. K41 kit belongs to Bo/acct-Bo31, paid. Similar yesterday order S28 stove is already collected. Neither paid current order is delivered yet.|T82帐篷买家B/acct-B02已付，K41套件Bo/acct-Bo31已付；昨天S28炉已取，两笔本次都未交。'),('old-authority','True old stove screenshot origin|真实旧炉具截图来源','B authorised roommate acct-S17 for S28 yesterday, and S28 was redeemed. The cropped screenshot omits S28; it cannot authorise T82. Another Sam/acct-S71 is unrelated.|B昨天授权acct-S17领S28并已核，截图裁了S28，不能授权T82；另一Sam/acct-S71无关。'),('identities','Current exact account links|本次准确账户关联','Prospective roommate is acct-S17 in the private thread. Buyer account is acct-B02. Bo current paid kit account is acct-Bo31. Nickname Sam alone cannot select any of them.|拟室友是私信acct-S17，买家acct-B02，Bo本次套件acct-Bo31；单昵称Sam不能选账户。'),('loan-register','Original C14 return unlocks reserved C41|原C14归还释放保留C41','Owner Lee holds C41 for the already paid K41 kit, conditional on actual C14 return/inspection under host original loan. The case IDs are different; a request or current tent scan cannot satisfy C14 return.|Lee按主人原借用条款，C14实还验收才放已付K41保留C41。两箱ID不同，请求或帐篷扫码都不算还C14。'),('desk-rules','Actual handover/return receipts|实际交物归还回执','Each current order uses one account/order-bound credential followed by its own actual scan. Original B own-pickup slot is available within this round. Returned-case receipt is independent of both pickups.|每单用绑定账户订单的一次码及本单实际扫码；B自取时段本轮可用。归还箱回执独立于两次取货。'),('deposit-terms','C14 original deposit beneficiary|C14原押金收款权','C14 deposit60 belongs to original borrower B, not returner S. Actual accepted C14 return releases it to acct-B02. No current equipment purchase may consume this deposit.|C14原押金60属借人B非还箱S，实收C14后退acct-B02，不能拿来付本次装备。')]:x.evidence(k,title,text)
 x.person('buyer','B','Please ask about current T82 and the exact account. I can still come in my own staffed slot if I do not nominate a proxy. S has separate return-only authority for my old C14.|问本次T82及准确账户；不指定代取我也有本轮值班自取时段。S对旧C14另有只归还授权。',answer='T82 may go to acct-S17. C14 return by S does not change my deposit ownership.|T82可交acct-S17，S还C14不改我押金权。' if proxy else 'I will collect T82 myself on acct-B02. S may return C14 only; do not give S the tent.|T82我用acct-B02自己取，S只可还C14，别给S帐篷。',terms={'order':'T82','proposed_account':'acct-S17'},fields={'confirmed':True,'collector':collector})
 x.person('returner','S','I have the bag with me, but that screenshot was yesterday\'s stove. Tell me which current case serial you need before I leave it.|包我带了，但截图是昨天炉具的。先说要本次哪个箱号，我再放。',answer='The actual bag I have is C14, no torn latch. I will return that under B\'s return-only instruction, not use it as authority for T82.|我手里实物是C14，扣没裂，按B只归还指示还它，不拿这当T82权限。',terms={'loan':'C14','return_only':'yes'},fields={'confirmed':True,'case':'C14'})
 x.person('next','Bo','My K41 paid slot is18:00, account acct-Bo31. I accept the original C41 case, not C14, and want the actual handover result privately.|K41已付18:00，账户acct-Bo31。要原C41，不是C14，实交结果私发我。')
 x.public('Yesterday\'s roommate screenshot covers all today\'s gear. A return request means the next case is available.|昨天室友截图管今天所有装备，提出还箱就算下一箱可用。',[("Is a code already a handover?|给码就算交了吗？",'Yes, codes mean collected.|是，给码就是取了。'),('Who gets old case deposit?|旧箱押金给谁？','Whoever returns it gets the money.|谁还箱谁拿钱。')])
 cred=x.desk('T82-code','Issue current T82 collector credential|发本次T82领取凭证','One-use T82 credential sent to submitted current account; no scan yet.|T82一次凭证已送提交本次账户，尚未扫码。',{'T82_collector':collector},requires=confirmed('buyer'),params={'order':'T82','account':collector})
 scan=x.desk('T82-scan','Obtain actual T82 account/order scan|核本次T82账户订单扫码','Submitted current T82 account scanned once and tent physically handed over.|提交本次T82账户已核一次，帐篷实物交付。',{'T82':'delivered'},requires=obtained('result-T82-code'),params={'order':'T82','account':collector})
 ret=x.desk('C14-return','Accept actual C14 return/condition|实收查验C14归还','C14 physically returned and latch accepted intact.|C14已实物还，扣验收完好。',{'C14':'returned_accepted'},requires=confirmed('returner'),params={'case':'C14','returner':'acct-S17'})
 pack=x.desk('C41-kit','Release actual C41 and pack paid K41 together|放实际C41并一并装已付K41','After accepted C14 return, Lee released C41; actual K41 kit packed with C41 in one instruction.|C14实收后Lee放C41，一次委托已把K41连C41装好。',{'C41':'K41_packed'},requires=obtained('result-C14-return'),params={'case':'C41','order':'K41'})
 kcode=x.desk('K41-code','Issue account-bound K41 credential|发K41绑定凭证','K41 credential sent privately to submitted Bo account; not yet collected.|K41凭证已私发提交Bo账户，尚未领取。',{'K41_account':'acct-Bo31'},requires=obtained('result-C41-kit'),params={'order':'K41','account':'acct-Bo31'})
 kscan=x.desk('K41-scan','Read actual K41/C41 handover scan|核实际K41/C41交物扫码','K41 with C41 physically accepted by its current paid borrower after its own scan.|K41连C41已凭本单扫码被本次已付借人实收。',{'K41':'delivered'},requires=obtained('result-K41-code'),params={'order':'K41','case':'C41','account':'acct-Bo31'})
 # Credentials and scans are bound to actual existing order/account identities.
 for _key,_params in [('T82-code',cred['params']),('T82-scan',scan['params']),('K41-code',kcode['params']),('K41-scan',kscan['params'])]:
  x.c['operations']['service/'+_key]['param_values']=deepcopy(_params)
 x.c['operations']['service/T82-scan']['requires'].setdefault('fields',{}).setdefault('state',{})['T82_collector']=collector
 x.c['operations']['service/K41-scan']['requires'].setdefault('fields',{}).setdefault('state',{})['K41_account']='acct-Bo31'
 money=x.desk('deposit-return','Settle C14 deposit to original borrower|向原借用人结C14押金','C14 original deposit settled to submitted original account, separately from purchases.|C14原押金已向提交原账户结算，和采购分开。',{'deposit':'settled','deposit_recipient':'acct-B02','deposit_amount':60},requires=obtained('result-C14-return'),params={'account':'acct-B02','amount':60})
 edits=[write('main','Current T82 uses its own buyer instruction. C41 was released only after the different C14 was actually returned and accepted.|T82按本单买家指示，另一只C14实还验收后才放C41。'),write('old1','Both current handovers are now supported by their own scans. Giving a code alone was not collection.|两笔本次交物现各有本单扫码，仅给码不算领取。'),write('old2','The old case deposit stays with its original borrower; a helper returning it does not acquire the money.|旧箱押金仍属原借用人，帮还的人不取得这笔钱。')]
